/**
 * Drives the filter bar in a real, offline Chromium through Drama Finder.
 * Checks what browser-only tests can check: the address bar and what typing costs the backend.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CustomerListBrowserTest extends AbstractBasePlaywrightIT {

    @LocalServerPort
    private int port;

    @Autowired
    private QueryLog queryLog;

    @Override
    public String getUrl() {
        return "http://localhost:" + port + "/";
    }

    @BeforeEach
    void openView() {
        page.navigate(getUrl());
        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
    }

    private com.microsoft.playwright.Locator nameField() {
        return page.getByPlaceholder("Filter by name");
    }

    private com.microsoft.playwright.Locator summary() {
        return page.getByText("Showing", new com.microsoft.playwright.Page.GetByTextOptions());
    }

    @Test
    void typingNarrowsTheListAndKeepsTheUrlInStep() {
        queryLog.clear();
        int historyBefore = ((Number) page.evaluate("history.length")).intValue();

        nameField().pressSequentially("makinen", new com.microsoft.playwright.Locator.PressSequentiallyOptions()
                .setDelay(30));
        assertThat(page.getByText("Showing 15 of 500")).isVisible();

        assertTrue(page.url().endsWith("/?name=makinen"), "address bar was " + page.url());
        assertEquals(historyBefore, ((Number) page.evaluate("history.length")).intValue(),
                "typing must replace the history entry, not add one per keystroke");

        assertTrue(queryLog.countQueries().size() <= 2,
                "typing a nine-letter name cost " + queryLog.countQueries().size() + " count queries");
    }

    @Test
    void urlFiltersAreAppliedAndShownOnOpening() {
        page.navigate(getUrl() + "?name=vir&status=ACTIVE,CLOSED");
        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);

        assertThat(nameField()).hasValue("vir");
        assertThat(page.getByText("Showing 10 of 500")).isVisible();
        MultiSelectComboBoxElement statuses = MultiSelectComboBoxElement.getByLabel(page, "Status");
        statuses.assertSelectedItems(CustomerStatus.ACTIVE.name(), CustomerStatus.CLOSED.name());
    }

    @Test
    void statusSelectionIsWrittenToTheUrl() {
        MultiSelectComboBoxElement statuses = MultiSelectComboBoxElement.getByLabel(page, "Status");
        statuses.selectItem(CustomerStatus.CLOSED.name());
        statuses.selectItem(CustomerStatus.ACTIVE.name());

        assertThat(page.getByText("Showing 333 of 500")).isVisible();
        assertTrue(page.url().endsWith("/?status=ACTIVE,CLOSED"), "address bar was " + page.url());
    }
}
