+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * Narrows the customer list by name and status. Applied by {@link CustomerRepository}.
+ *
+ * <p>The name is split on whitespace into terms, and every term must appear as a
+ * substring of the customer's first name or last name. Matching ignores case and
+ * accents, so {@code makinen} matches {@code Mäkinen}.
+ *
+ * @param name     free text typed by the user; blank matches every name
+ * @param statuses statuses to show; empty shows every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /** A predicate that is true for the customers this filter lets through. */
+    public Predicate<Customer> asPredicate() {
+        List<String> terms = terms();
+        return customer -> (statuses.isEmpty() || statuses.contains(customer.status()))
+                && matchesName(customer, terms);
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = fold(customer.firstName());
+        String last = fold(customer.lastName());
+        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    private List<String> terms() {
+        String folded = fold(name).strip();
+        return folded.isEmpty() ? List.of() : List.of(WHITESPACE.split(folded));
+    }
+
+    /** Lower-cases {@code text} and strips accents, so that comparisons ignore both. */
+    static String fold(String text) {
+        String decomposed = Normalizer.normalize(text.toLowerCase(Locale.ROOT), Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("");
+    }
+}
